function validate([nums, x, y]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of nums is between 1 and 10^9.';
  if (!Number.isInteger(y) || y < 1) return 'y is at least 1.';
  if (!Number.isInteger(x) || x <= y || x > 1e9) return 'x must be greater than y and at most 10^9.';
  return null;
}

