function minOperations(nums, x, y) {
  const extra = x - y;
  let low = 0;
  let high = Math.ceil(Math.max(...nums) / y);
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    let picks = 0;
    for (const value of nums) {
      const remaining = value - mid * y;
      if (remaining > 0) {
        picks += Math.ceil(remaining / extra);
      }
    }
    if (picks <= mid) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

