function minOperations(nums, x, y) {
  // Breadth-first search over the actual states, each value clipped at 0.
  const start = nums.map(v => Math.max(0, v));
  let frontier = [start];
  const seen = new Set([start.join(',')]);
  for (let steps = 0; ; steps++) {
    const next = [];
    for (const state of frontier) {
      if (state.every(v => v === 0)) return steps;
      for (let i = 0; i < state.length; i++) {
        const after = state.map((v, j) => Math.max(0, v - (j === i ? x : y)));
        const key = after.join(',');
        if (!seen.has(key)) { seen.add(key); next.push(after); }
      }
    }
    frontier = next;
  }
}

