function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 4);
    const top = pick(1, 14);
    const y = pick(1, 4);
    const x = y + pick(1, 6);
    return [Array.from({ length: n }, () => pick(1, top)), x, y];
  }
  const n = pick(1500, 2000);
  const shape = Math.floor(rand() * 3);
  const y = shape === 0 ? pick(1, 50) : shape === 1 ? pick(1000, 100000) : pick(1, 1000000);
  const x = shape === 2 ? pick(y + 1, 1000000000) : y + pick(1, 5000);
  const top = shape === 1 ? 1000000000 : pick(1000000, 1000000000);
  return [Array.from({ length: n }, () => pick(1, top)), x, y];
}
